            font-size: 14px
        }

        .problem-card {
            background: #f8faf8;
            border: 1px solid #e5e7eb;
            border-radius: 12px;
            padding: 20px;
            text-align: center;
            transition: all .3s
        }

        .problem-card:hover {
            border-color: #558255;
            transform: translateY(-3px)
        }

        .acor-container input[type=checkbox] {
            display: none
        }

        .acor-container .acor-body {
            max-height: 0;
            overflow: hidden;
            transition: all .3s ease
        }

        .acor-container input[type=checkbox]:checked+label+.acor-body {
            max-height: 300px;
            padding: 0 20px 20px
        }

        .acor-container label {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 18px 20px;
            background: #f8f9fa;
            border-radius: 10px;
            cursor: pointer;
            border: 1px solid #e5e7eb;
            font-weight: 500
        }

        .acor-container label:hover {
            background: #f0f0f0;
            border-color: #558255
        }

        .acor-container label::after {
            content: \'+\';
            font-size: 22px;
            color: #558255;
            width: 30px;
            height: 30px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: #fff;
            border-radius: 50%;
            transition: all .3s
        }

        .acor-container input[type=checkbox]:checked+label::after {
            content: \'−\';
            background: #558255;
            color: #fff
        }

        .hero-carousel .swiper-slide {
            height: 500px
        }

        .hero-carousel .swiper-slide img {
