                    }
                },
                {
                    "@type": "Question",
                    "name": "Что входит в рабочую документацию?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Генплан, дендроплан, схема вертикальной планировки, план дорожно-транспортной сети, разбивочный чертеж, схема освещения, схема дренажа и ливневой канализации, схема автополива, посадочный чертеж, ассортиментная ведомость."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Сколько стоит проект?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Стоимость зависит от площади участка и состава проекта. Мы составляем индивидуальное коммерческое предложение после консультации."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Сколько времени занимает разработка?",
